sysauto_script.script:
var gr = new GlideRecord('x_enno_gatenow_grant_review');
gr.addEncodedQuery('state=1^u_start_dateISNOTEMPTY^review_deadlineISNOTEMPTY'); 
gr.query();

while (gr.next()) {
    var reviewerList = gr.reviewer.toString();
    if (!reviewerList) continue; // Skip if no reviewers defined

    var reviewerIds = reviewerList.split(',');
    var totalGroups = reviewerIds.length;
    var currentIndex = parseInt(gr.u_current_index) || 0;

    // 1. Calculate Total Duration available for the whole process
    var startGdt = new GlideDateTime(gr.u_start_date);
    var deadlineGdt = new GlideDateTime(gr.review_deadline);

    var totalDurationMs = deadlineGdt.getNumericValue() - startGdt.getNumericValue();

    if (totalDurationMs > 0 && totalGroups > 0) {
        // 2. Calculate exact time allowed per group (Dynamic)
        var msPerGroup = totalDurationMs / totalGroups;

        // 3. Determine when the CURRENT group's window expires
        // Formula: Start Date + (TimePerGroup * (CurrentIndex + 1))
        var currentGroupWindowEndMs = startGdt.getNumericValue() + (msPerGroup * (currentIndex + 1));
        var nowMs = new GlideDateTime().getNumericValue();

        // 4. Check if we need to advance
        if (nowMs >= currentGroupWindowEndMs) {
            var nextIndex = currentIndex + 1;

            if (nextIndex < totalGroups) {
                // MOVE TO NEXT GROUP
                gr.u_current_index = nextIndex;
                gr.assignment_group = reviewerIds[nextIndex];

                var daysLeft = Math.round(msPerGroup / (1000 * 60 * 60 * 24) * 10) / 10;
                gr.work_notes = "Dynamic Window Expired. Moving to Group " + (nextIndex + 1) + 
                                ". Each group is allocated ~" + daysLeft + " days.";

                gs.eventQueue('x_enno_gatenow.grant.group.assigned', gr, gr.assignment_group, '');
                gr.update();
            } else {
                // ALL GROUPS FINISHED
                gr.state = 3; // Overall Complete
                gr.assignment_group = '';
                gr.work_notes = "Final dynamic review window closed. Process complete.";
                gr.update();
            }
        }
    }
}
